_z3:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n// Fragment shader para GameMaker Studio 2\nvarying vec4 v_vColour;\nvarying vec2 v_vTexcoord;\n\nuniform float tileSize;\nuniform float time;\nuniform vec2 resolution;\n\nvoid main()\n{\n    vec2 uv = v_vTexcoord * resolution;\n    vec2 tilePos = mod(uv, tileSize);\n\n    float contraction = time; // anim_progress de 0 a 1\n    float lineWidth = 1.5;\n    float margin = tileSize * 0.3 * (1.0 - contraction);\n\n    bool lineX = (tilePos.x < lineWidth + margin) || (tilePos.x > tileSize - lineWidth - margin);\n    bool lineY = (tilePos.y < lineWidth + margin) || (tilePos.y > tileSize - lineWidth - margin);\n\n    if (lineX || lineY)\n        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0); // negro opaco\n    else\n        gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);\n}\n\n",
